// Un recargo "global": visible desde cualquier función
const recargoIva = 0.21;

function precioFinal(neto) {
  const iva = neto * recargoIva;   // «iva» es local: vive solo mientras dura esta llamada
  return neto + iva;
}

function descuentoPorVolumen(neto) {
  const iva = "otro iva";          // otra «iva», distinta: cada función tiene la suya
  return neto > 1000 ? neto * 0.9 : neto;
}

console.log(precioFinal(1000));    // 1210
console.log(descuentoPorVolumen(2000)); // 1800

// Desde afuera, la «iva» de precioFinal no existe
try {
  console.log(iva);
} catch (e) {
  console.log(e.name + ": " + e.message);
}

// Ámbito de bloque (let, const) contra ámbito de función (var)
function repartir(paquetes) {
  for (let i = 0; i < paquetes; i++) {
    const etiqueta = "PAQ-" + i;     // existe solo dentro de las llaves del for
  }
  try { console.log(i); } catch (e) { console.log("let: " + e.message); }
  try { console.log(etiqueta); } catch (e) { console.log("const: " + e.message); }

  for (var j = 0; j < paquetes; j++) {
    var ultima = "PAQ-" + j;         // var ignora las llaves: vive en toda la función
  }
  console.log("var j:", j, "| var ultima:", ultima);
}
repartir(3);

// Sombreado: una variable interna con el mismo nombre tapa a la de afuera
