// Una clausura: la función interna se lleva consigo la variable de afuera
function crearContador(inicio) {
  let cuenta = inicio;            // local de crearContador
  return function () {            // esta función interna «recuerda» a cuenta
    cuenta = cuenta + 1;
    return cuenta;
  };
}

const remitosA = crearContador(100);   // crearContador ya terminó y devolvió
const remitosB = crearContador(5000);

console.log(remitosA());  // 101
console.log(remitosA());  // 102
console.log(remitosB());  // 5001
console.log(remitosA());  // 103: cada contador tiene su propia «cuenta»

// Desde afuera no hay forma de tocar cuenta directamente
try { console.log(cuenta); } catch (e) { console.log(e.name + ": " + e.message); }

