// Dibujamos a mano lo que el motor hace solo: una lista que hace de pila de llamadas
const pila = [];
function entrar(nombre, datos) {
  pila.push(nombre + "(" + datos + ")");
  console.log("  ".repeat(pila.length - 1) + "entra  → pila: [" + pila.join(" | ") + "]");
}
function salir(valor) {
  const nombre = pila.pop();
  console.log("  ".repeat(pila.length) + "sale   ← " + nombre + " devuelve " + valor);
  return valor;
}

function redondear(x) {
  entrar("redondear", x);
  return salir(Math.round(x * 100) / 100);
}
function costoEnvio(km) {
  entrar("costoEnvio", km);
  return salir(redondear(500 + km * 12.5));
}
function totalPedido(km, mercaderia) {
  entrar("totalPedido", km + ", " + mercaderia);
  return salir(mercaderia + costoEnvio(km));
}

console.log("resultado:", totalPedido(40, 10000));
console.log("pila al terminar:", pila.length, "elementos");

function pesar(caja) {
  return caja * 2;
}
function etiquetar(caja) {
  return "E" + pesar(caja);
}
function despachar(a, b) {
  const x = etiquetar(a);
  const y = etiquetar(b);
  return x + y;
}
console.log(despachar(1, 2));

// Recursión: una función que se llama a sí misma. Cada llamada apila un marco más.
function sumarHasta(n) {
  if (n === 0) return 0;           // caso base: acá se corta
  return n + sumarHasta(n - 1);
}
console.log("sumarHasta(1000) =", sumarHasta(1000));

// Sin caso base, o con un n enorme, la pila se llena
let profundidad = 0;
function bajar() {
  profundidad++;
  bajar();                         // nunca vuelve: no hay nada que lo detenga
}
try {
  bajar();
} catch (e) {
  console.log(e.name + ": " + e.message);
  console.log("se llegó a unas", profundidad, "llamadas anidadas (depende del motor)");
}
console.log("el programa sigue vivo y la pila ya se vació");

try { sumarHasta(1000000); } catch (e) { console.log("sumarHasta(1000000) →", e.name); }

// La misma suma con un bucle no apila nada
function sumarConBucle(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}
console.log("sumarConBucle(1000000) =", sumarConBucle(1000000));

const a = { nombre: "Bebidas", sub: [] };
const b = { nombre: "Gaseosas", sub: [a] };   // por error, Gaseosas contiene a Bebidas
a.sub.push(b);                                // y Bebidas contiene a Gaseosas
function contar(cat) {
  let n = 1;
  for (const s of cat.sub) n += contar(s);
  return n;
}
try { contar(a); } catch (e) { console.log(e.name + ": " + e.message); }
